        legend_row.addWidget(self._alpha_sl)
        layout.addLayout(legend_row)

        # ── plots ─────────────────────────────────────────────────────────────
        self.f_plot   = pg.PlotWidget(title="Corrected F + baselines")
        self.dff_plot = pg.PlotWidget(title="dFF")
        self.dff_plot.setXLink(self.f_plot)

