class _BiToggleLabel(QLabel):
    """'Option A / Option B' clickable label.

    The active option is rendered bold black; the inactive one is light gray.
    Emits ``toggled`` after each flip (by click or programmatic toggle()).
    """
    toggled = pyqtSignal()

    def __init__(self, option_a: str, option_b: str,
                 active: int = 0, parent=None):
        super().__init__(parent)
        self._options = (option_a, option_b)
        self._active  = active % 2
        self.setCursor(Qt.PointingHandCursor)
        self._refresh()

    def active(self) -> int:
        return self._active

    def setActive(self, idx: int, emit: bool = True):
        idx = idx % 2
        if self._active == idx:
            return
        self._active = idx
        self._refresh()
        if emit:
            self.toggled.emit()

    def toggle(self):
        self.setActive(1 - self._active)

    def mousePressEvent(self, ev):
        self.toggle()
        super().mousePressEvent(ev)

    def _refresh(self):
        parts = []
        for i, opt in enumerate(self._options):
            if i == self._active:
                parts.append(f"<b style='color:#111'>{opt}</b>")
            else:
                parts.append(f"<span style='color:#bbb'>{opt}</span>")
        self.setText(" / ".join(parts))


